            exceptions: ["This app drills the MBE only: for the MEE and MPT, check your board and use separate practice"],
            cite: "NCBE MEE Subject Matter Outline",
            citeAsk: "Which NCBE document lists the subjects tested on the MEE?",
            ex: [
              { facts: "A candidate in a UBE jurisdiction drops Business Associations because it is not on the MBE.", result: "Risky: it is on the MEE, so her essays may test it." },
            ],
            terms: ["MEE", "MPT"],
            quiz: [
              { t: "tf", q: "Business Associations is tested on the MBE.", a: false, why: "The MBE tests seven subjects, and Business Associations is not one of them." },
              { t: "mcq", q: "Which subject is tested on the legacy MEE but not on the MBE?", options: ["Business Associations", "Evidence", "Real Property"], a: "Business Associations", why: "Business Associations appears on the MEE (and NextGen); Evidence and Real Property are MBE subjects." },
              { t: "tf", q: "Because Trusts and Estates left the MEE in July 2026, it appears nowhere on the legacy UBE.", a: false, why: "NCBE says Trusts and Estates and Family Law are tested regularly through the MPT through February 2028." },
            ],
            status: "exam", src: "NCBE MEE page (ncbex.org/exams/mee); NCBE MEE Subject Matter Outline; NCBE MBE exam page; format.md §4",
